sys_variable_value.value:
(function execute(inputs, outputs) {
    var gr_import_set = new GlideRecord("sys_import_set");
    gr_import_set.addQuery("schedule_import",inputs.import_job_sys_id);
    gr_import_set.addEncodedQuery("stateINloaded,loading");
    gr_import_set.setLimit(1);
    gr_import_set.query();
    if(gr_import_set.next()) outputs.import_set_sys_id = gr_import_set.getValue("sys_id");
})(inputs, outputs);

